action.code:
size_t cell = ckh_isearch(ckh, searchkey);
if (cell == SIZE_T_MAX) {
    return true;
}
ckhc_t *tab_cell = &ckh->tab[cell];
if (key != NULL) {
    *key = (void *)tab_cell->key;
}
if (data != NULL) {
    *data = (void *)tab_cell->data;
}
return false;

